with kept as (select s.* from orders s where not exists (select 1 from payments x where x.order_id = s.id and x.paid_at <= s.order_date)) select customer_id, case when amount >= 1760 then 'HIGH' else 'LOW' end as amount_tier, avg(shipping_fee) as avg_shipping_fee, approx_percentile(amount, array(0.25, 0.5, 0.75)) as amount_quartiles, size(collect_set(channel)) as num_channels, grouping_id() as grouping_id from kept group by grouping sets ((customer_id, case when amount >= 1760 then 'HIGH' else 'LOW' end), (customer_id))
